import unittest
from urllib.parse import parse_qsl, urlsplit
from links import with_query

class WithQueryTests(unittest.TestCase):
    def test_encoding_and_order(self):
        params = {'a b': 'hello world', '한글': 'café', 'a&b': 'x=y&z', 'a=b': 'x+y'}
        result = with_query('https://example.com/path', params)
        self.assertEqual(result, 'https://example.com/path?a+b=hello+world&%ED%95%9C%EA%B8%80=caf%C3%A9&a%26b=x%3Dy%26z&a%3Db=x%2By')
        self.assertEqual(parse_qsl(urlsplit(result).query), list(params.items()))

    def test_existing_query_and_fragment(self):
        url = 'https://example.com/path?x=a%20b&x=%2f&bare#section?raw&text'
        self.assertEqual(with_query(url, {'q': 'a & b'}), 'https://example.com/path?x=a%20b&x=%2f&bare&q=a+%26+b#section?raw&text')

    def test_url_forms(self):
        for url, expected in [('/path#frag', '/path?q=x#frag'), ('/path#', '/path?q=x#'), ('/path?', '/path?q=x'), ('/path?x=1&', '/path?x=1&q=x'), ('/path&', '/path&?q=x')]:
            with self.subTest(url=url):
                self.assertEqual(with_query(url, {'q': 'x'}), expected)

    def test_empty_mapping(self):
        for url in ['/path', '/path?', '/path?x=%20#', '/path#fragment']:
            self.assertEqual(with_query(url, {}), url)

unittest.main()
